try:
    import copy as _lpv2_copy
    import math as _lpv2_math
    import random as _lpv2_random
    import re as _lpv2_re
    from difflib import SequenceMatcher as _LPV2SequenceMatcher
except Exception:
    _lpv2_copy = None
    _lpv2_math = None
