def _leap_v16_extract_required_experiments(idea_result):
    parsed = _leap_v16_safe_dict(getattr(idea_result, 'parsed', {}))
    for key in ('required_experiments','experiments','tests'):
        xs = _leap_v16_safe_list(parsed.get(key))
        if xs: return xs[:8]
