        ('time_or_phase', ['time','delay','phase','lag','feedback','時間','遅延','位相','フィードバック']),
        ('risk_or_constraint', ['risk','constraint','degradation','crossover','resistance','制約','リスク','劣化','抵抗','漏れ']),
