def _leap_r15a_filter_term_list_universal(terms, max_terms=None, allowlist=None):
    out = []
    seen = set()
    rejected = []
    allow = set()
    if allowlist:
        for a in allowlist:
            try:
                allow.add(str(a).strip())
            except Exception:
                continue
    for raw in terms or []:
        raw_str = '' if raw is None else str(raw).strip()
        if raw_str and raw_str in allow:
            cleaned = raw_str
        else:
            cleaned = _leap_r15a_filter_node_label_universal(raw)
        if not cleaned:
            rejected.append(raw)
            continue
        if cleaned in seen:
            continue
        seen.add(cleaned)
        out.append(cleaned)
        if max_terms is not None and len(out) >= int(max_terms):
            break
    return out, rejected


